// One-off generator script: converts PT Sans TTF files (which support
// Cyrillic — required for the Russian-language PDF dossier; jsPDF's core
// fonts do not cover Cyrillic glyphs) into base64 TypeScript modules that
// jsPDF can embed via doc.addFileToVFS()/doc.addFont(). The generated files
// are checked in under src/lib/pdf/fonts and the TTF sources are not needed
// at runtime — this script only matters if the font ever needs regenerating.
//
// To regenerate: download the source TTFs to %TEMP%/PTSans-Regular.ttf and
// %TEMP%/PTSans-Bold.ttf, e.g.:
//   https://raw.githubusercontent.com/google/fonts/main/ofl/ptsans/PT_Sans-Web-Regular.ttf
//   https://raw.githubusercontent.com/google/fonts/main/ofl/ptsans/PT_Sans-Web-Bold.ttf
// then run `node scripts/gen-pdf-fonts.mjs`.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const outDir = new URL("../src/lib/pdf/fonts/", import.meta.url);
mkdirSync(outDir, { recursive: true });

function convert(srcPath, exportName, outFile) {
  const buf = readFileSync(srcPath);
  const base64 = buf.toString("base64");
  const content =
    `// Auto-generated by scripts/gen-pdf-fonts.mjs from PT Sans (SIL Open Font License 1.1).\n` +
    `// PT Sans supports Cyrillic, required to render the Russian-language PDF dossier.\n` +
    `// Do not edit by hand.\n` +
    `export const ${exportName} = "${base64}";\n`;
  writeFileSync(new URL(outFile, outDir), content, "utf8");
  console.log(`Wrote ${outFile}: ${(content.length / 1024).toFixed(0)} KB`);
}

convert(join(tmpdir(), "PTSans-Regular.ttf"), "PT_SANS_REGULAR_BASE64", "pt-sans-regular.ts");
convert(join(tmpdir(), "PTSans-Bold.ttf"), "PT_SANS_BOLD_BASE64", "pt-sans-bold.ts");
